/*
 * INA219 Solar Panel Tracker
 * Dual-LDR sun tracker with INA219 power monitoring.
 *
 * Wiring:
 *   INA219  — VCC→5V, GND→GND, SDA→A4, SCL→A5
 *   OLED    — VCC→5V, GND→GND, SDA→A4, SCL→A5  (shared I2C bus)
 *   Servo   — SIG→D9,  VCC→5V, GND→GND
 *   LDR (L) — VCC→5V, AO→A0,  GND→GND
 *   LDR (R) — VCC→5V, AO→A1,  GND→GND
 */

#include <Wire.h>
#include <Servo.h>
#include <Adafruit_INA219.h>
#include <Adafruit_SSD1306.h>

Adafruit_INA219 ina219;
Adafruit_SSD1306 oled(128, 64, &Wire, -1);
Servo trackerServo;

const int LDR_LEFT  = A0;
const int LDR_RIGHT = A1;
const int SERVO_PIN = 9;

int servoAngle = 90;
const int TOLERANCE = 15;
const int STEP      = 2;

void setup() {
  Serial.begin(9600);
  ina219.begin();
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  trackerServo.attach(SERVO_PIN);
  trackerServo.write(servoAngle);

  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SSD1306_WHITE);
  oled.setCursor(10, 20);
  oled.print("Solar Tracker");
  oled.setCursor(10, 36);
  oled.print("INA219 + Servo");
  oled.display();
  delay(1500);
}

void loop() {
  int leftVal  = analogRead(LDR_LEFT);
  int rightVal = analogRead(LDR_RIGHT);

  if (leftVal - rightVal > TOLERANCE) {
    servoAngle -= STEP;
  } else if (rightVal - leftVal > TOLERANCE) {
    servoAngle += STEP;
  }
  servoAngle = constrain(servoAngle, 0, 180);
  trackerServo.write(servoAngle);

  float busVoltage = ina219.getBusVoltage_V();
  float current    = ina219.getCurrent_mA();
  float power      = ina219.getPower_mW();

  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SSD1306_WHITE);

  oled.setCursor(0, 0);
  oled.print("--- Solar Tracker ---");

  oled.setCursor(0, 14);
  oled.print("Angle: ");
  oled.print(servoAngle);
  oled.print((char)247);

  oled.setCursor(0, 26);
  oled.print("V: ");
  oled.print(busVoltage, 2);
  oled.print(" V");

  oled.setCursor(0, 36);
  oled.print("I: ");
  oled.print(current, 1);
  oled.print(" mA");

  oled.setCursor(0, 46);
  oled.print("P: ");
  oled.print(power, 1);
  oled.print(" mW");

  oled.setCursor(0, 56);
  oled.print("L:");
  oled.print(leftVal);
  oled.print(" R:");
  oled.print(rightVal);

  oled.display();

  Serial.print("Angle=");
  Serial.print(servoAngle);
  Serial.print(" V=");
  Serial.print(busVoltage, 2);
  Serial.print(" I=");
  Serial.print(current, 1);
  Serial.print(" P=");
  Serial.print(power, 1);
  Serial.print(" LDR_L=");
  Serial.print(leftVal);
  Serial.print(" LDR_R=");
  Serial.println(rightVal);

  delay(200);
}
